from collections import Counter, defaultdict

class NGramModel:
  """
  tokenize() performs word level tokenization (splitted by white space)
  training() trains the n_gram model. Concretely, it calculates the frequency of a word given its preceding contexts in the training data (hamlet in this assignment).
  predict() picks out the most probable next word given a context h.
  generate() repeatedly applies predict() to obtain a sequence. max_length determines how many times predict() is repeated.
  """
  def __init__(self, n, data):
    self.n = n
    self.data = data
    self.model = None

  def tokenize(self):
    tokenized_data = self.data.lower().split()
    return tokenized_data

  def training(self):
    n_gram = defaultdict(Counter)
    tokenized_data = self.tokenize()
    for i in range(len(tokenized_data)-self.n+1):
      h = tuple(tokenized_data[i:i+self.n-1]) #history/context
      w = tokenized_data[i+self.n-1]
      n_gram[h][w] += 1
    self.model = n_gram

  def predict(self, h):
    if self.n == 1:
      h = ()
    if isinstance(h, str):
      h = tuple(h.lower().split())
    if h not in self.model:
      print("Error: Unknown Context")
      return None
    return self.model[h].most_common(1)[0][0]

  def generate(self, max_length, h=None):
    if isinstance(h, str):
      sent = h.lower()
    else:
      sent = ""
    if self.n == 1:
      h = tuple()
    if isinstance(h, str):
      h = tuple(h.lower().split())
    h = h[len(h) - (self.n - 1):len(h)]  # trim context
    for i in range(max_length):
      w = self.predict(h)
      if w is None:
        break
      sent += " " + w
      h = h[1:] + (w,)
    return sent

from collections import Counter, defaultdict

class BackOffNGramModel:
  """
  tokenize() performs word level tokenization (splitted by white space)
  training() trains the n_gram model. Concretely, it calculates the frequency of a word given its preceding contexts in the training data (hamlet in this assignment).
  predict() picks out the most probable next word given a context h.
  generate() repeatedly applies predict() to obtain a sequence. max_length determines how many times predict() is repeated.
  """
  def __init__(self, n, data):
    self.n = n
    self.data = data
    self.model = None

  def tokenize(self):
    tokenized_data = self.data.lower().split()
    return tokenized_data

  def training(self):
    tokenized_data = self.tokenize()
    n_gram_list = []
    for m in range(1, self.n + 1):
      n_gram = defaultdict(Counter)
      for i in range(len(tokenized_data) - m + 1):
        h = tuple(tokenized_data[i:i + m - 1])  # history/context
        w = tokenized_data[i + m - 1]
        n_gram[h][w] += 1
      n_gram_list.append(n_gram)
    self.model = n_gram_list

  def predict(self, h=None):
    idx = self.n - 1  # list index starts from 0
    n_gram = self.model[idx]
    if self.n == 1:
      h = ()
    if isinstance(h, str):
      h = tuple(h.lower().split())
    if h not in n_gram:
      reduced_h = h
      for i in range(1, self.n):
        reduced_h = h[0 + i:]  # context needs to be reduced
        n_gram = self.model[idx - i]  # use lower n-gram
        if idx - i == 0:  # unigram
          reduced_h = tuple()
        if reduced_h in n_gram:
          return n_gram[reduced_h].most_common(1)[0][0]
    else:
      return n_gram[h].most_common(1)[0][0]

  def generate(self, max_length, h=None):
    if isinstance(h, str):
      sent = h.lower()
    else:
      sent = ""
    if self.n == 1:
      h = tuple()
      sent = ""  # unigram has no context
    if isinstance(h, str):
      h = tuple(h.lower().split())
    h = h[len(h) - (self.n - 1):len(h)]  # trim context
    for i in range(max_length):
      w = self.predict(h)
      if w is None:
        break
      sent += " " + w
      h = h[1:] + (w,)
    return sent
